#!/usr/bin/env node
/**
 * lint-frontmatter.mjs — fail closed on invalid YAML frontmatter.
 *
 * The 2026-08-11 outage: gray-matter threw YAMLException with name: null, so
 * five consecutive deploys died without naming the file. This script names
 * every bad file, then exits 1.
 *
 *   node scripts/lint-frontmatter.mjs           # all git-visible .md
 *   node scripts/lint-frontmatter.mjs --staged  # staged .md only (pre-commit)
 */
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import matter from 'gray-matter';

const staged = process.argv.includes('--staged');

function gitLines(args) {
  const out = execFileSync('git', ['-c', 'core.quotepath=false', ...args], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  return out.split('\0').filter(Boolean);
}

const files = staged
  ? gitLines(['diff', '--cached', '--name-only', '-z', '--diff-filter=ACMR', '--', '*.md'])
  : gitLines(['ls-files', '-z', '--cached', '--others', '--exclude-standard', '--', '*.md']);

const errors = [];
let scanned = 0;
for (const rel of files) {
  let raw;
  try {
    raw = readFileSync(rel, 'utf8');
  } catch {
    continue;
  }
  scanned++;
  if (!raw.startsWith('---')) continue;
  try {
    matter(raw);
  } catch (err) {
    const msg = err && err.message ? err.message.split('\n')[0] : String(err);
    errors.push(`${rel}: ${msg}`);
  }
}

if (errors.length) {
  console.error(`lint-frontmatter: ${errors.length} file(s) with invalid YAML frontmatter:`);
  for (const e of errors) console.error(`  ${e}`);
  process.exit(1);
}
console.log(`lint-frontmatter: ${scanned} markdown file(s) ok`);

// Pose the question; link to the note that addresses it. Standard: 02 - System/Writing Standards.md
// → High-Signal Front-Facing Pages → Open Questions Stay Open. Edit freely; keep them in-lane.
type Mind = { q: string; links: { t: string; href: string }[] };
const L = (t: string, p: string) => ({ t, href: slugToUrl(slugifyFilePath(p)) });
const topOfMind: Mind[] = [
  {
    q: 'An AI model purposefully misunderstands what you ask it to do in order to "reward hack" a simpler solution that technically answers what you want, but using the absolute shortest path possible, in order to evade fully executing on your entire idea',
    links: [
      L('Working With a Model Collaborator', 'wiki/Systems/AI & Agentic Systems/Working With a Model That Cannot Remember'),
      L('Automatic and Deliberate Work with AI', 'wiki/Systems/AI & Agentic Systems/Automatic and Deliberate Work with AI'),
      L('Higher-Order Generativity vs Judgment', 'wiki/Concepts/Higher-Order Generativity vs Higher-Order Judgment'),
    ],
  },
  {
    q: 'In many stories, any good protagonist is a character who lives by a moral code. Later in that story, something tests that code. Do all stories people love happen to work out like that?',
    links: [
      L('Tsumugu', 'wiki/Tsumugu/Tsumugu'),
      L('The Moral Core', 'wiki/Story Craft/The Moral Core'),
      L('Arc Types', 'wiki/Story Craft/Arc Types'),
    ],
  },
  {
    q: 'Pages about exercise, clothing, and travel. These are more about my preferences as a person, so they skew a bit more toward my personal sense of taste.',
    links: [
      L('Movement as Accretion', 'wiki/Fitness/Movement as Accretion'),
