{
  "tool": "subscribe_github_ci",
  "description": "Subscribe this Cloud Agent to terminal GitHub CI results on one branch. Waits until every check run and commit-status context on a commit is terminal, then delivers one commit-wide result: success when none failed, or failure with the failed check names. Delivers only when the commit is still the head of the subscribed branch at delivery time; results for commits superseded by a newer push are dropped (the newer head notifies on its own CI). Fork PRs and branchless status events are not covered. Failures always deliver; a success delivers only as this subscription's first result or when it flips a previously delivered failure — repeated greens are not delivered. Subscribing to the repository's default branch (e.g. main) is one-shot: it delivers the next terminal result on that branch and then closes itself, so it cannot be used to watch every merge to the default branch. To wait for a PR's CI, subscribe to the PR's head branch instead. After subscribing, state what you are waiting for and end your turn; the event arrives as a follow-up notification in this conversation.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "options": {
        "type": "object",
        "properties": {
          "repo": {
            "type": "string"
          },
          "branch": {
            "type": "string"
          }
        },
        "required": [
          "repo",
          "branch"
        ]
      },
      "expiresInSeconds": {
        "type": "number"
      }
    },
    "required": [
      "options"
    ]
  }
}
